APP_ROLE = "axar_app"
TENANT_TABLES = ("staff", "staff_roles", "approvals")
# Looked up by the SHA-256 of a secret token BEFORE the tenant is known, so
# they cannot be tenant-filtered by RLS; every query on them is by token hash
# or carries an explicit tenant filter in code.
LOOKUP_TABLES = ("devices", "enrollment_codes", "auth_sessions")


def secure_identity_tables() -> None:
    policy = "tenant_id = current_setting('app.tenant_id', true)"
    for table in TENANT_TABLES:
        op.execute(f"ALTER TABLE {table} ENABLE ROW LEVEL SECURITY")
        op.execute(f"CREATE POLICY tenant_isolation ON {table} USING ({policy}) WITH CHECK ({policy})")
    # Failed attempts with an unknown tenant are audited with tenant_id NULL.
    op.execute("ALTER TABLE auth_events ENABLE ROW LEVEL SECURITY")
    op.execute(f"CREATE POLICY tenant_isolation ON auth_events USING ({policy}) "
               f"WITH CHECK (tenant_id IS NULL OR {policy})")
    grants = [f"GRANT SELECT, INSERT, UPDATE, DELETE ON {t} TO {APP_ROLE}" for t in TENANT_TABLES]
    grants += [f"GRANT SELECT, INSERT, UPDATE ON {t} TO {APP_ROLE}" for t in LOOKUP_TABLES]
    grants.append(f"GRANT SELECT, INSERT ON auth_events TO {APP_ROLE}")  # append-only audit
    grants.append(f"GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO {APP_ROLE}")
    body = "; ".join(grants)
    op.execute(f"DO $$ BEGIN IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = '{APP_ROLE}') "
               f"THEN {body}; END IF; END $$")


